L13_1 = "<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> LET'S GOOOO!!! CANARY SQUAD!!!\n<color=#ffd34c>\226\150\160 \226\150\160</color> Was there ever a challenger who fought this well against the champion before?\n<color=#ffd34c>\226\150\160 \226\150\160\226\150\160</color> Man, Canary Squad is a legend.\n<color=#ffd34c>\226\150\160\226\150\160 \226\150\160</color> Who cares if they're third-grade citizens now?\n<color=#ffd34c>\226\150\160\226\150\160 \226\150\160</color> I just want Canary Squad to win now. LOL!\n<color=#ffd34c>\226\150\160\226\150\160 \226\150\160</color> But it's too hard to watch. I'm tearing up...\n<color=#ffd34c>\226\150\160 \226\150\160 \226\150\160</color> Ozymandias' reign lasted long enough. LMAO!\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> TBH, isn't Canary Squad far greater than the champion who's a Counter?"
