L13_1 = "<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> LET'S GOO!!! Ti\225\187\131u \196\144\225\187\153i Canary!!!\n<color=#ffd34c>\226\150\160 \226\150\160</color> \196\144\195\163 t\225\187\171ng c\195\179 ng\198\176\225\187\157i th\195\161ch \196\145\225\186\165u n\195\160o chi\225\186\191n \196\145\225\186\165u v\225\187\155i nh\195\160 v\195\180 \196\145\225\187\139ch m\195\160 \196\145\225\187\137nh nh\198\176 v\225\186\173y tr\198\176\225\187\155c \196\145\195\162y ch\198\176a?\n<color=#ffd34c>\226\150\160 \226\150\160\226\150\160</color> Tr\225\187\157i \225\186\161, Ti\225\187\131u \196\144\225\187\153i Canary l\195\160 m\225\187\153t huy\225\187\129n tho\225\186\161i.\n<color=#ffd34c>\226\150\160\226\150\160 \226\150\160</color> Ai quan t\195\162m li\225\187\135u b\195\162y gi\225\187\157 h\225\187\141 c\195\179 ph\225\186\163i l\195\160 c\195\180ng d\195\162n h\225\186\161ng ba hay kh\195\180ng?\n<color=#ffd34c>\226\150\160\226\150\160 \226\150\160</color> T\195\180i ch\225\187\137 mu\225\187\145n Ti\225\187\131u \196\145\225\187\153i Canary gi\195\160nh chi\225\186\191n th\225\186\175ng ngay b\195\162y gi\225\187\157. LOL!\n<color=#ffd34c>\226\150\160\226\150\160 \226\150\160</color> Nh\198\176ng kh\195\179 xem qu\195\161. T\195\180i \196\145ang kh\195\179c...\n<color=#ffd34c>\226\150\160 \226\150\160 \226\150\160</color> Tri\225\187\129u \196\145\225\186\161i c\225\187\167a Ozymandias \196\145\195\163 k\195\169o d\195\160i \196\145\225\187\167 l\195\162u r\225\187\147i. LMAO!\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> N\195\160y, ch\225\186\179ng ph\225\186\163i Ti\225\187\131u \196\145\225\187\153i Canary m\225\186\161nh h\198\161n nhi\225\187\129u so v\225\187\155i nh\195\160 v\195\180 \196\145\225\187\139ch l\195\160 Counter sao?"
