L11_1[L12_1] = L13_1
L12_1 = "m_SubTitle_DEU"
L13_1 = "<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> Los gehts!!! Canary Trupp!!!\n<color=#ffd34c>\226\150\160 \226\150\160</color> Gab es schon mal einen Gegner, der Ozymandias so gut das Wasser reichen konnte?\n<color=#ffd34c>\226\150\160 \226\150\160\226\150\160</color> Der Canary Trupp ist eine echte Legende.\n<color=#ffd34c>\226\150\160\226\150\160 \226\150\160</color> Es ist vollkommen egal, dass sie B\195\188rger dritter Klasse sind.\n<color=#ffd34c>\226\150\160\226\150\160 \226\150\160</color> Ich hoffe echt, dass der Canary Trupp gewinnen wird! LOL!\n<color=#ffd34c>\226\150\160\226\150\160 \226\150\160</color> Ich kann kaum zuschauen, weil es mir das Herz zerrei\195\159t.\n<color=#ffd34c>\226\150\160 \226\150\160 \226\150\160</color> Ozymandias kann ihre Krone endlich mal an einen neuen Champion weitergeben!\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> Mal ehrlich: Ist der Canary Trupp zum jetzigen Zeitpunkt nicht schon besser als der Counter-Champion?"
L11_1[L12_1] = L13_1
L12_1 = "m_SubTitle_FRA"
L13_1 = "<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> Allez les canariiiis !!!\n<color=#ffd34c>\226\150\160 \226\150\160</color> C'est la premi\195\168re fois que quelqu'un se bat aussi bien contre Ozymandias !\n<color=#ffd34c>\226\150\160 \226\150\160\226\150\160</color> L'escouade Canari est vraiment l\195\169gendaire !\n<color=#ffd34c>\226\150\160\226\150\160 \226\150\160</color> On s'en fiche que ce soit des citoyens de 3e zone maintenant !\n<color=#ffd34c>\226\150\160\226\150\160 \226\150\160</color> J'aimerais trop que l'escouade Canari gagne lol\n<color=#ffd34c>\226\150\160\226\150\160 \226\150\160</color> Je suis limite triste que \195\167a se termine T-T\n<color=#ffd34c>\226\150\160 \226\150\160 \226\150\160</color> Ozymandias est rest\195\169e fid\195\168le \195\160 elle-m\195\170me lol\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> \195\128 ce niveau l\195\160, je trouve les canaris encore plus \195\169patants que la championne, m\195\170me si c'est une Counter !"
